<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$d=['client_id'=>'','categorie_id'=>'','description_besoin'=>'','budget_maximum'=>'','date_effet_souhaitee'=>date('Y-m-d',strtotime('+7 days')),'date_expiration'=>date('Y-m-d',strtotime('+30 days'))];$errors=[];if($id){$s=$db->prepare('SELECT * FROM demandes_devis WHERE id=?');$s->execute([$id]);$d=array_merge($d,$s->fetch()?:exit('Demande introuvable.'));}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(array_keys($d) as $f)if(isset($_POST[$f]))$d[$f]=trim((string)$_POST[$f]);if(!(int)$d['client_id']||!(int)$d['categorie_id']||$d['date_effet_souhaitee']==='')$errors[]='Client, branche et date d’effet sont obligatoires.';if(!$errors){$v=['client'=>(int)$d['client_id'],'agent'=>(int)$_SESSION['user']['id'],'cat'=>(int)$d['categorie_id'],'besoin'=>$d['description_besoin']?:null,'budget'=>$d['budget_maximum']!==''?(float)$d['budget_maximum']:null,'effet'=>$d['date_effet_souhaitee'],'expiration'=>$d['date_expiration']?:null];if($id){$v['id']=$id;$db->prepare("UPDATE demandes_devis SET client_id=:client,agent_id=:agent,categorie_id=:cat,description_besoin=:besoin,budget_maximum=:budget,date_effet_souhaitee=:effet,date_expiration=:expiration WHERE id=:id AND statut IN ('brouillon','complete')")->execute($v);}else{$next=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM demandes_devis')->fetchColumn();$v['numero']='DEM-'.date('Y').'-'.str_pad((string)$next,4,'0',STR_PAD_LEFT);$db->prepare('INSERT INTO demandes_devis(client_id,agent_id,categorie_id,numero_demande,description_besoin,budget_maximum,date_effet_souhaitee,date_expiration) VALUES(:client,:agent,:cat,:numero,:besoin,:budget,:effet,:expiration)')->execute($v);$id=(int)$db->lastInsertId();}audit('ENREGISTREMENT','demande_devis',$id);flash('success','Demande enregistrée. Complétez maintenant le questionnaire.');redirect('demandes/questionnaire.php?id='.$id);}}
$clients=$db->query("SELECT id,numero_client,type_client,nom,prenom,raison_sociale FROM clients WHERE statut<>'inactif' ORDER BY COALESCE(raison_sociale,nom),prenom")->fetchAll();$categories=$db->query('SELECT id,libelle FROM categories_risque ORDER BY libelle')->fetchAll();$title=$id?'Modifier la demande':'Nouvelle demande';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell"><div class="page-heading"><h1 class="h3"><?= e($title) ?></h1><a class="btn btn-outline-secondary" href="index.php">Retour</a></div><?php if($errors): ?><div class="alert alert-danger"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" class="card card-body needs-validation" novalidate><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="row g-3"><div class="col-md-7"><label class="form-label">Client *</label><select class="form-select" name="client_id" required><option value="">Sélectionner un client</option><?php foreach($clients as $c): $n=$c['type_client']==='entreprise'?$c['raison_sociale']:trim($c['prenom'].' '.$c['nom']);?><option value="<?= $c['id'] ?>" <?= (int)$d['client_id']==(int)$c['id']?'selected':'' ?>><?= e($c['numero_client'].' - '.$n) ?></option><?php endforeach ?></select></div><div class="col-md-5"><label class="form-label">Branche de risque *</label><select class="form-select" name="categorie_id" required><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (int)$d['categorie_id']==(int)$c['id']?'selected':'' ?>><?= e($c['libelle']) ?></option><?php endforeach ?></select></div><div class="col-12"><label class="form-label">Besoin exprimé</label><textarea class="form-control" rows="4" name="description_besoin"><?= e($d['description_besoin']) ?></textarea></div><div class="col-md-4"><label class="form-label">Budget maximum (FCFA)</label><input type="number" min="0" class="form-control" name="budget_maximum" value="<?= e((string)$d['budget_maximum']) ?>"></div><div class="col-md-4"><label class="form-label">Date d’effet souhaitée *</label><input type="date" class="form-control" name="date_effet_souhaitee" value="<?= e($d['date_effet_souhaitee']) ?>" required></div><div class="col-md-4"><label class="form-label">Expiration</label><input type="date" class="form-control" name="date_expiration" value="<?= e($d['date_expiration']) ?>"></div></div><div class="text-end mt-4"><button class="btn btn-primary">Enregistrer et répondre</button></div></form></div><?php require __DIR__.'/../../includes/footer.php'; ?>
